select energy_manager.load_cards($cards$[
{"id":"p4-b06-002","paper":4,"topic":"Fan and Blower Performance","kind":"fact","front":"Define static, dynamic and total pressure, and state how they add up.","back":"Static pressure is the absolute pressure at a point minus the atmospheric reference pressure. Dynamic (velocity) pressure is the rise in static pressure when moving air is brought to rest without loss. Total pressure = static pressure + dynamic pressure.","explain":"Total minus static gives the velocity pressure that a Pitot tube reads, so the three are linked by this sum.","flash":false,"source":"BEE Book 4 Ch 06 p123","order":4275},
{"id":"p4-b06-003","paper":4,"topic":"Fan and Blower Performance","kind":"fact","front":"What is the difference between fan shaft power and motor input power?","back":"Fan shaft power is the mechanical power supplied to the fan shaft. Motor input power is the electrical power supplied to the motor terminals.","explain":"The gap between them is the motor and transmission losses, which the book accounts for with motor efficiency and transmission efficiency.","flash":false,"source":"BEE Book 4 Ch 06 p123","order":4276},
{"id":"p4-b06-004","paper":4,"topic":"Fan and Blower Performance","kind":"fact","front":"What is the book's fan efficiency formula, and how is static pressure rise defined?","back":"Fan efficiency = air power ÷ fan shaft power. In the book's form: η = Q × ΔPs ÷ (102 × fan shaft kW) × 100%, with Q in m³/s and ΔPs = discharge static − suction static in mmWC.","explain":"The 102 is the book's conversion constant. Static pressure rise is the discharge reading minus the suction reading, both taken relative to atmosphere.","flash":false,"source":"BEE Book 4 Ch 06 p123","order":4277},
{"id":"p4-b06-005","paper":4,"topic":"Fan and Blower Performance","kind":"fact","front":"What kind of fan does the book's field procedure cover, and which standard does it reference?","back":"Centrifugal fans and blowers, for assessing performance and efficiency. The reference is British Standard BS 848 Part 1 (methods of testing performance).","explain":"This is a field test procedure for installed fans, not a laboratory test.","flash":false,"source":"BEE Book 4 Ch 06 p124","order":4278},
{"id":"p4-b06-006","paper":4,"topic":"Fan and Blower Performance","kind":"fact","front":"What must be checked before site tests on a fan begin?","back":"The fan and its associated equipment must be working properly at rated speed, and operating conditions must be stable, with steady temperatures, densities and system resistance.","explain":"The book requires these conditions before readings are taken, so the flow and pressure values reflect steady operation.","flash":false,"source":"BEE Book 4 Ch 06 p124","order":4279},
{"id":"p4-b06-007","paper":4,"topic":"Fan and Blower Performance","kind":"fact","front":"How long must the test length be, and how is equivalent diameter found?","back":"At least 2 × De (twice the equivalent diameter). For a rectangular duct De = 2LW ÷ (L + W), where L and W are the duct sides. For a circular duct, De is the diameter.","explain":"The test length must be straight, of uniform cross-section and free of obstructions, so the airflow is steady where it is measured.","flash":false,"source":"BEE Book 4 Ch 06 p124","order":4280},
{"id":"p4-b06-008","paper":4,"topic":"Fan and Blower Performance","kind":"fact","front":"Where must the flow measurement plane be placed on the inlet side and on the outlet side of a fan?","back":"Inlet side (preferred): the downstream end of the test length is at least 0.75 De from the fan inlet, or from the inlet cone if there is an inlet box. Outlet side: the upstream end of the test length is at least 3 De from the fan outlet.","explain":"Bends and obstructions disturb airflow for a long distance, so the measurement is kept away from them.","flash":false,"source":"BEE Book 4 Ch 06 p124","order":4281},
{"id":"p4-b06-009","paper":4,"topic":"Fan and Blower Performance","kind":"fact","front":"Why should static pressure readings be taken close to the fan?","back":"So that the pressure losses between the measuring plane and the fan can be calculated from friction factor data, without adding excessive uncertainty to the fan pressure figure.","explain":"This is the book's reason for placing pressure planes near the fan. If the test length is conveniently close, it can serve for pressure readings too.","flash":false,"source":"BEE Book 4 Ch 06 p124","order":4282},
{"id":"p4-b06-010","paper":4,"topic":"Fan and Blower Performance","kind":"fact","front":"How far must pressure measurement planes be from the fan and from duct features?","back":"No closer than 0.25 De from the fan inlet and no closer than 4 De from the fan outlet. Also at least 4 De downstream of any bend, expander or obstruction.","explain":"These distances keep pressure readings out of the disturbed flow next to the fan and next to duct features.","flash":true,"source":"BEE Book 4 Ch 06 p125","order":4283},
{"id":"p4-b06-011","paper":4,"topic":"Fan and Blower Performance","kind":"fact","front":"How does a Pitot tube read velocity pressure, and what makes the reading accurate?","back":"Static and total connections go to opposite sides of a manometer. The static pressure cancels, so the manometer shows the velocity pressure (Pt − Ps). The nozzle must point straight into and parallel to the air stream, the connecting tubes must be airtight, and the instruments must be calibrated.","explain":"In the nested Pitot design the inner tube takes total pressure and radial holes on the outer tube sense static pressure.","flash":false,"source":"BEE Book 4 Ch 06 p126","order":4284},
{"id":"p4-b06-012","paper":4,"topic":"Fan and Blower Performance","kind":"fact","front":"Why are traverse readings needed in a duct, and for which duct sizes does the book recommend them?","back":"Air velocity is not uniform across a duct. Friction slows air near the walls, so velocity is highest at the centre. Readings at a formal pattern of equal-area points give the average. The book recommends traverses for ducts 100 mm in diameter or larger.","explain":"The average velocity is the arithmetic mean of the velocities calculated at all traverse points.","flash":false,"source":"BEE Book 4 Ch 06 p127","order":4285},
{"id":"p4-b06-013","paper":4,"topic":"Fan and Blower Performance","kind":"fact","front":"How many traverse points does the book require for round and for rectangular ducts?","back":"Round ducts: readings at centres of equal concentric areas, at least 10 points for a 1 m diameter duct. Rectangular ducts: a minimum of 16 and a maximum of 64 readings, at centres of equal rectangular areas.","explain":"So a 1 m × 1 m rectangular duct needs at least 16 traverse points.","flash":true,"source":"BEE Book 4 Ch 06 p128","order":4286},
{"id":"p4-b06-014","paper":4,"topic":"Fan and Blower Performance","kind":"problem","front":"For a 1 m diameter round duct (radius 0.5 m), what are the positions of the 10 traverse points measured from one wall?","back":"0.0255, 0.0815, 0.1465, 0.226, 0.342, 0.658, 0.774, 0.8535, 0.9185 and 0.9745 m.","explain":"The book's round-duct example. Positions come in symmetric pairs about the centre, using the equal-area factors from its traverse figure.","flash":false,"source":"BEE Book 4 Ch 06 p128","steps":[{"prompt":"Note the radius and the position rule.","answer":"R = 0.5 m. Each point is at R ± (factor × R), using the book's factors 0.949, 0.837, 0.707, 0.548 and 0.316.","explain":"Points sit at the centres of equal concentric areas, measured from the duct wall."},{"prompt":"Compute the outermost pair.","answer":"0.5 − 0.949 × 0.5 = 0.0255 m; 0.5 + 0.949 × 0.5 = 0.9745 m.","explain":"The outermost point uses the largest factor."},{"prompt":"Compute the next pair.","answer":"0.5 − 0.837 × 0.5 = 0.0815 m; 0.5 + 0.837 × 0.5 = 0.9185 m.","explain":"Each pair is symmetric about the centre line."},{"prompt":"Compute the remaining pairs.","answer":"Factor 0.707: 0.1465 m and 0.8535 m. Factor 0.548: 0.226 m and 0.774 m. Factor 0.316: 0.342 m and 0.658 m.","explain":"Five symmetric pairs give the ten points the book recommends for a 1 m duct."}],"order":4287},
{"id":"p4-b06-015","paper":4,"topic":"Fan and Blower Performance","kind":"problem","front":"For a 1.4 m × 0.8 m rectangular duct with 16 traverse points, what is the size of each area, and where is the first point?","back":"Each area is 0.35 m × 0.20 m (0.07 m²). The first point is 0.175 m from one side and 0.10 m from the other.","explain":"The book's rectangular-duct example. Equal-area rectangles are laid out and each point sits at the centre of one rectangle.","flash":false,"source":"BEE Book 4 Ch 06 p129","steps":[{"prompt":"Find the total duct area.","answer":"1.4 × 0.8 = 1.12 m².","explain":"Total area is divided into equal areas for the traverse."},{"prompt":"Find the area per point.","answer":"1.12 ÷ 16 = 0.07 m².","explain":"Sixteen equal areas are needed for sixteen points."},{"prompt":"Lay out the grid.","answer":"1.4 m ÷ 4 = 0.35 m columns; 0.8 m ÷ 4 = 0.20 m rows. This gives 4 × 4 = 16 rectangles of 0.35 m × 0.20 m.","explain":"A 4 by 4 grid of equal rectangles gives 16 areas of 0.07 m² each."},{"prompt":"Find the first point's coordinates.","answer":"Centre at 0.35 ÷ 2 = 0.175 m across and 0.20 ÷ 2 = 0.10 m along the other side.","explain":"Each point is at the centre of its own rectangle."}],"order":4288},
{"id":"p4-b06-016","paper":4,"topic":"Fan and Blower Performance","kind":"fact","front":"What pitot tube coefficient should be used when the manufacturer's value is not known?","back":"Assume 0.85. Velocity = Cp × √(2 × 9.81 × Δp ÷ ρ), with Δp in mmWC and ρ in kg/m³.","explain":"The book gives 0.85 as the default assumption when the manufacturer's coefficient is not available.","flash":false,"source":"BEE Book 4 Ch 06 p129","order":4289},
{"id":"p4-b06-017","paper":4,"topic":"Fan and Blower Performance","kind":"fact","front":"How is gas density at flow conditions calculated?","back":"ρ = P × M ÷ (R × T), where P is absolute pressure (mmWC), M is molecular weight (kg/kmol), T is absolute temperature (K), and R = 847.84 mmWC·m³/(kmol·K).","explain":"P must be absolute, not gauge pressure, so atmospheric pressure is included before calculating density.","flash":false,"source":"BEE Book 4 Ch 06 p129","order":4290},
{"id":"p4-b06-018","paper":4,"topic":"Fan and Blower Performance","kind":"fact","front":"How is the molecular weight of a dry flue gas calculated?","back":"M = (%CO₂ × 44 + %O₂ × 32 + %CO × 28 + %N₂ × 28 + %SO₂ × its molecular weight) ÷ 100, using the dry gas analysis.","explain":"The book's cement kiln example uses the CO₂, O₂, CO and N₂ terms with the dry composition.","flash":false,"source":"BEE Book 4 Ch 06 p130","order":4291},
{"id":"p4-b06-019","paper":4,"topic":"Fan and Blower Performance","kind":"fact","front":"How is velocity measured with a rotating vane anemometer, and how is flow then found?","back":"Hold the anemometer stationary at each traverse point for at least 1 minute. Correct each reading to the anemometer calibration. Average the corrected velocities, then multiply by the duct area to get the volume flow.","explain":"This is the anemometer alternative to the Pitot tube method. Keep the instrument calibration up to date.","flash":false,"source":"BEE Book 4 Ch 06 p130","order":4292},
{"id":"p4-b06-020","paper":4,"topic":"Fan and Blower Performance","kind":"fact","front":"What is the formula for volume flow in a duct?","back":"Flow (m³/s) = Area (m²) × average velocity (m/s).","explain":"The average velocity comes from the traverse points, so the area must be the actual duct cross-section.","flash":true,"source":"BEE Book 4 Ch 06 p130","order":4293},
{"id":"p4-b06-021","paper":4,"topic":"Fan and Blower Performance","kind":"fact","front":"How is fan power measured or estimated on site?","back":"Use a clamp-on power meter where possible. Otherwise measure voltage and current and assume a power factor of 0.9: P = √3 × V × I × cos φ.","explain":"The 0.9 power factor is the book's fallback, and it is less accurate than direct metering.","flash":false,"source":"BEE Book 4 Ch 06 p130","order":4294},
{"id":"p4-b06-022","paper":4,"topic":"Fan and Blower Performance","kind":"fact","front":"What transmission efficiencies does the book assume for direct coupling, flat belt and V-belt drives?","back":"Directly coupled with properly lubricated precision spur gears: 0.98 per step. Flat belt: 0.97. V-belt: 0.95.","explain":"Use these when the fan is not connected directly to the motor, because transmission efficiency enters the fan shaft power calculation.","flash":true,"source":"BEE Book 4 Ch 06 p130","order":4295},
{"id":"p4-b06-023","paper":4,"topic":"Fan and Blower Performance","kind":"fact","front":"How is fan shaft power derived from motor input power?","back":"Fan shaft power = motor input power × motor efficiency at the corresponding loading × transmission efficiency.","explain":"Motor efficiency depends on loading, so read it at the measured load rather than at full load.","flash":false,"source":"BEE Book 4 Ch 06 p130","order":4296},
{"id":"p4-b06-024","paper":4,"topic":"Fan and Blower Performance","kind":"fact","front":"If a fan is driven by a non-electric prime mover, what should be measured?","back":"The fuel consumption (oil, steam, compressed air and so on), specified in place of an overall power figure.","explain":"The book recommends measuring the prime mover's fuel input rather than trying to express the drive as a single electrical power value.","flash":false,"source":"BEE Book 4 Ch 06 p130","order":4297},
{"id":"p4-b06-025","paper":4,"topic":"Fan and Blower Performance","kind":"fact","front":"Name five factors that can affect fan performance or distort test results.","back":"Leakage, recirculation or other system defects; inaccurate estimate of flow resistance; erroneous use of standardised test data; excessive loss in a component too close to the fan outlet; a bend or component too close to the fan inlet. Site measurement error also applies.","explain":"The book lists these in its section on factors that could affect performance. Keep the duct straight near the fan where possible.","flash":false,"source":"BEE Book 4 Ch 06 p131","order":4298},
{"id":"p4-b06-026","paper":4,"topic":"Fan and Blower Performance","kind":"problem","front":"A cement kiln exhaust (dry basis: CO₂ 24.7%, O₂ 5.1%, CO 0.1%, N₂ 70.1%) is at −655 mmWC static and 316 °C. The velocity pressure is 16.39 mmWC, atmospheric pressure 10334 mmWC, Pitot constant 0.85, duct area 8.3 m². What is the volumetric flow?","back":"About 158.1 m³/s, which the book gives as 5,69,304 m³/h.","explain":"The book's first solved example. Recalculating the density from the stated inputs gives about 0.62 kg/m³, not the 0.64 the book uses, so the book's flow answer follows its 0.64 value.","flash":false,"source":"BEE Book 4 Ch 06 p131","steps":[{"prompt":"Find the molecular weight of the dry gas.","answer":"(24.7 × 44 + 5.1 × 32 + 0.1 × 28 + 70.1 × 28) ÷ 100 = 32.16 kg/kmol.","explain":"Each gas percentage is multiplied by its molecular weight and summed."},{"prompt":"Find the absolute pressure and temperature.","answer":"P = 10334 − 655 = 9679 mmWC. T = 273 + 316 = 589 K.","explain":"Density needs absolute pressure and absolute temperature."},{"prompt":"Find the gas density.","answer":"ρ = 9679 × 32.16 ÷ (847.84 × 589) ≈ 0.64 kg/m³ (book value).","explain":"The book uses 0.64 kg/m³. Recalculating gives about 0.62, so check the arithmetic if you are asked to derive it."},{"prompt":"Find the volumetric flow.","answer":"Q = A × Cp × √(2 × 9.81 × 16.39 ÷ 0.64) = 8.3 × 0.85 × 22.42 = 158.14 m³/s.","explain":"Flow is duct area times the pitot coefficient times the velocity from the velocity pressure."},{"prompt":"Convert to m³/h.","answer":"158.14 × 3600 = 5,69,304 m³/h.","explain":"Seconds to hours is a factor of 3600."}],"order":4299},
{"id":"p4-b06-027","paper":4,"topic":"Fan and Blower Performance","kind":"problem","front":"At the best efficiency point of a centrifugal fan, the curves read 36 inches H₂O static pressure, 2750 CFM flow and 29 hp shaft power. Find the static pressure in mmWC, the flow in m³/h, the shaft power in kW, the static efficiency and the motor input at 90% motor efficiency.","back":"914.4 mmWC; about 4672 m³/h (≈1.3 m³/s); 21.6 kW; about 54%; motor input about 24 kW.","explain":"The book's curve-reading example. Values are read from a chart, so the answers are approximate.","flash":false,"source":"BEE Book 4 Ch 06 p132","steps":[{"prompt":"Convert the static pressure.","answer":"36 × 25.4 = 914.4 mmWC.","explain":"One inch of water is 25.4 mmWC."},{"prompt":"Convert the flow.","answer":"2750 CFM = 4672.28 m³/h ≈ 1.3 m³/s.","explain":"The book's conversion for the flow reading."},{"prompt":"Convert the shaft power.","answer":"29 hp × 0.746 = 21.6 kW.","explain":"One horsepower is about 0.746 kW."},{"prompt":"Calculate the static efficiency.","answer":"η = 1.3 × 914.4 ÷ (102 × 21.6) = 0.54, so 54%.","explain":"Air power is flow times static pressure divided by 102, then divided by shaft kW."},{"prompt":"Find the motor input at 90% motor efficiency.","answer":"21.6 ÷ 0.9 = 24 kW.","explain":"Motor input equals shaft power divided by motor efficiency."}],"order":4300},
{"id":"p4-b06-028","paper":4,"topic":"Fan and Blower Performance","kind":"problem","front":"A double-inlet fan (design 292 m³/s, 610 mmWC) has suction −20 mmWC and discharge 470 mmWC. Two ducts of 1.029 × 5.502 m each carry an average velocity of 29 m/s. The motor draws 220 A at 6.6 kV with PF 0.9 and efficiency 0.94, and is directly coupled. Find the total flow, static pressure rise and static fan efficiency.","back":"Total flow ≈ 328.6 m³/s. Static pressure rise 490 mmWC. Static fan efficiency ≈ 74%.","explain":"The book's third solved example, a palletising plant fan. The fan is designed for 78% efficiency, so the result is below design.","flash":false,"source":"BEE Book 4 Ch 06 p133","steps":[{"prompt":"Find the motor input and fan shaft power.","answer":"Motor input = √3 × 6.6 × 220 × 0.9 = 2263 kW. Shaft = 2263 × 0.94 × 1 = 2127 kW.","explain":"Motor efficiency applies first, then transmission efficiency, which is 1 for a direct coupling."},{"prompt":"Find the air density.","answer":"ρ = (10334 − 20) × 28.84 ÷ (847.84 × 305) = 1.15 kg/m³.","explain":"The velocity was measured on the suction side, so the static pressure there is used with atmospheric pressure."},{"prompt":"Find the total flow.","answer":"One duct: 29 × 1.029 × 5.502 = 164.3 m³/s. Both ducts: 164.3 × 2 = 328.6 m³/s.","explain":"Each duct is calculated separately and then added."},{"prompt":"Find the static pressure rise.","answer":"470 − (−20) = 490 mmWC.","explain":"Pressure rise is discharge static minus suction static."},{"prompt":"Calculate the static fan efficiency.","answer":"η = 328.6 × 490 × 100 ÷ (102 × 2127) = 74%.","explain":"The 102 is the book's conversion constant."}],"order":4301},
{"id":"p4-b06-029","paper":4,"topic":"Fan and Blower Performance","kind":"problem","front":"In the double-inlet fan's sample calculation, one traverse point shows a velocity pressure of 70 mmWC. With density 1.15 kg/m³, Pitot coefficient 0.85 and duct area 1.029 × 5.502 m², what is the flow?","back":"About 166.3 m³/s.","explain":"The book's sample calculation. One point's velocity gives a flow close to the traverse average of 29 m/s, but a full traverse is the proper method.","flash":false,"source":"BEE Book 4 Ch 06 p134","steps":[{"prompt":"Find the velocity at the point.","answer":"√(2 × 9.81 × 70 ÷ 1.15) = 34.56 m/s, before the coefficient.","explain":"Velocity pressure is converted to velocity using the density."},{"prompt":"Apply the Pitot coefficient.","answer":"0.85 × 34.56 = 29.4 m/s.","explain":"The coefficient corrects the ideal velocity to the real Pitot reading."},{"prompt":"Find the flow through the duct area.","answer":"Area = 1.029 × 5.502 = 5.661 m². Flow = 5.661 × 29.4 ≈ 166.3 m³/s (book value).","explain":"Flow is area times the velocity, as in the book's sample."}],"order":4302},
{"id":"p4-b06-030","paper":4,"topic":"Fan and Blower Performance","kind":"fact","front":"Why is the double-inlet fan's static efficiency (74%) below its design value of 78%?","back":"The damper was partly closed, so the fan runs at lower flow than design, away from its best efficiency point.","explain":"Partly closing a damper throttles the flow and moves the operating point away from the best efficiency point, which lowers fan efficiency.","flash":true,"source":"BEE Book 4 Ch 06 p135","order":4303},
{"id":"p4-b07-001","paper":4,"topic":"Pump Performance","kind":"fact","front":"What does a centrifugal pump do to the liquid?","back":"It transforms mechanical energy from a rotating impeller into the kinetic and potential energy the system needs, so the liquid can flow through a pipe or rise to a higher level.","explain":"Pumping adds energy to a liquid to move it from one point to another. The energy lets the liquid do work such as flowing through pipes or lifting to a higher level.","flash":false,"source":"BEE Book 4 Ch 07 p139","order":4304},
{"id":"p4-b07-002","paper":4,"topic":"Pump Performance","kind":"fact","front":"What is the most critical aspect of energy efficiency in a pumping system?","back":"Matching the pump to the load (the system).","explain":"An efficient pump that is mismatched to its system can still run at very poor efficiency. Efficiency can also drop over time because of deposits in the impellers, so a performance assessment is needed to find the real operating efficiency.","flash":true,"source":"BEE Book 4 Ch 07 p139","order":4305},
{"id":"p4-b07-003","paper":4,"topic":"Pump Performance","kind":"fact","front":"Name the two purposes of a pump performance test.","back":"(1) Determine pump efficiency at the operating condition. (2) Determine the system resistance and operating duty point, and compare them with design.","explain":"The test shows how the pump is really performing. Comparing the results against design values reveals where corrective action is needed.","flash":false,"source":"BEE Book 4 Ch 07 p139","order":4306},
{"id":"p4-b07-004","paper":4,"topic":"Pump Performance","kind":"fact","front":"How does pump capacity Q vary with rotational speed N?","back":"Q is proportional to N (directly proportional).","explain":"Capacity is directly proportional to speed, so changing the speed changes the flow in the same proportion. This is the basis for flow control by speed in the chapter's examples.","flash":true,"source":"BEE Book 4 Ch 07 p139","order":4307},
{"id":"p4-b07-005","paper":4,"topic":"Pump Performance","kind":"fact","front":"Name the three heads in common use in pumps.","back":"Static head, velocity head and friction head.","explain":"Total developed head is the difference between discharge and suction pressure. It is the net work done on unit weight of liquid between the pump inlet and discharge.","flash":false,"source":"BEE Book 4 Ch 07 p139","order":4308},
{"id":"p4-b07-006","paper":4,"topic":"Pump Performance","kind":"fact","front":"How does friction head vary with flow in a pipe system?","back":"Roughly as the square of the flow through the system.","explain":"Friction head in pipes, valves and fittings rises steeply as flow increases. This is why system resistance grows quickly at higher flows.","flash":true,"source":"BEE Book 4 Ch 07 p139","order":4309},
{"id":"p4-b07-007","paper":4,"topic":"Pump Performance","kind":"fact","front":"What is system resistance?","back":"The sum of the frictional head and the total static head.","explain":"System resistance is the head the pump must overcome at a given flow. Plotting it against flow gives the system curve used to find the duty point.","flash":false,"source":"BEE Book 4 Ch 07 p139","order":4310},
{"id":"p4-b07-008","paper":4,"topic":"Pump Performance","kind":"fact","front":"How is pump efficiency defined?","back":"Fluid power and useful work done by the pump, divided by the power input at the pump shaft.","explain":"Efficiency compares the useful hydraulic output with the shaft power delivered to the pump. It is the key figure in a pump performance test.","flash":true,"source":"BEE Book 4 Ch 07 p139","order":4311},
{"id":"p4-b07-009","paper":4,"topic":"Pump Performance","kind":"fact","front":"Which three parameters are needed to determine pump efficiency in the field?","back":"Flow, head and power.","explain":"Flow is the most crucial, because online flow meters are rarely available in most pumping systems. Head comes from pressure gauge or level readings, and power from a power analyser.","flash":false,"source":"BEE Book 4 Ch 07 p140","order":4312},
{"id":"p4-b07-010","paper":4,"topic":"Pump Performance","kind":"fact","front":"Name the four flow measurement methods for pump testing.","back":"Tracer method (BS 5857); ultrasonic flow measurement; tank filling method; installation of an online flowmeter.","explain":"The method depends on availability and site conditions. An online flowmeter is the best option where the measurement is critical and periodic.","flash":false,"source":"BEE Book 4 Ch 07 p140","order":4313},
{"id":"p4-b07-011","paper":4,"topic":"Pump Performance","kind":"fact","front":"Which tracer is normally used in the tracer method, and what is the method best suited for?","back":"Sodium chloride; it is particularly suited to cooling water flow measurement.","explain":"A tracer is injected at an accurately measured constant rate, and samples are taken downstream once it is fully mixed. Its sensitivity and accuracy make the method suitable for cooling water.","flash":false,"source":"BEE Book 4 Ch 07 p140","order":4314},
{"id":"p4-b07-012","paper":4,"topic":"Pump Performance","kind":"fact","front":"What is the tracer-method equation for cooling water mass flow?","back":"q_ew = q₁ × C₁ / C₂, where q₁ is the tracer injection rate (kg/s), C₁ is the injected tracer concentration and C₂ is the downstream concentration during the constant 'plateau' period.","explain":"Samples must be taken where the tracer is completely mixed with the water. The ratio of concentrations gives the dilution, and multiplying the injection rate by it gives the water mass flow.","flash":false,"source":"BEE Book 4 Ch 07 p140","order":4315},
{"id":"p4-b07-013","paper":4,"topic":"Pump Performance","kind":"problem","front":"Tracer is injected at 0.2 kg/s with a concentration of 0.05 kg/kg. The downstream plateau concentration is 0.001 kg/kg. Find the cooling water mass flow.","back":"10 kg/s of cooling water.","explain":"Built directly on the tracer formula in this chapter. The dilution ratio is 0.05 / 0.001 = 50, so the water flow is 50 times the tracer rate, 50 × 0.2 = 10 kg/s.","flash":false,"source":"BEE Book 4 Ch 07 p140","steps":[{"prompt":"Write the tracer formula.","answer":"q_ew = q₁ × C₁ / C₂","explain":"The tracer injected is diluted by the cooling water, so the water flow follows from the concentration ratio."},{"prompt":"Substitute the values.","answer":"q_ew = 0.2 × 0.05 / 0.001","explain":"q₁ = 0.2 kg/s, C₁ = 0.05 kg/kg and C₂ = 0.001 kg/kg."},{"prompt":"Evaluate the result.","answer":"= 10 kg/s","explain":"The mass flow is 10 kg/s, which can be converted to m³/hr only if the water density is known."}],"order":4316},
{"id":"p4-b07-014","paper":4,"topic":"Pump Performance","kind":"fact","front":"What are the site requirements for an ultrasonic (Doppler) flow meter?","back":"Measure in a long pipe run free from disturbance by bends, tees and fittings. Hammer the pipe gently so scale and rust fall out. For better accuracy, replace a section with new pipe.","explain":"The meter is non-invasive, but disturbed flow and a scaled pipe wall both degrade the reading. These steps make the measurement section as clean and undisturbed as possible.","flash":false,"source":"BEE Book 4 Ch 07 p141","order":4317},
{"id":"p4-b07-015","paper":4,"topic":"Pump Performance","kind":"fact","front":"How is flow measured by the tank filling method?","back":"Stop the outlet flow from the tank, then note the change in tank level over a specified period. Use the tank's internal dimensions from design drawings, or measure them directly if drawings are not available.","explain":"This suits open flow systems such as a pump filling an overhead tank or a sump. Flow is the volume change divided by the time taken.","flash":false,"source":"BEE Book 4 Ch 07 p141","order":4318},
{"id":"p4-b07-016","paper":4,"topic":"Pump Performance","kind":"fact","front":"How is suction head found for a pump?","back":"From the pump inlet pressure gauge, converted to metres (1 kg/cm² = 10 m). If there is no gauge, measure the level difference from the sump water level to the pump centreline.","explain":"Suction head can be negative when the water level is below the pump, as in one of the chapter's examples. The head is then subtracted from the discharge head.","flash":true,"source":"BEE Book 4 Ch 07 p141","order":4319},
{"id":"p4-b07-017","paper":4,"topic":"Pump Performance","kind":"fact","front":"Why must a discharge pressure gauge be fitted for a pump test?","back":"Discharge head is read from the discharge-side pressure gauge, so a gauge must be installed there if one is not already fitted.","explain":"Total head is discharge head minus suction head. Without a discharge reading, the total head and so the hydraulic power cannot be calculated.","flash":false,"source":"BEE Book 4 Ch 07 p141","order":4320}
]$cards$::jsonb);
